def main() -> Int {

    // Prompt the user for the CSV file name
    var file_name:Str
    while True {
        println("Enter the name of the CSV file:")
        file_name = Console.readLine().trim()

        if len(file_name) == 0 {
            println("Error: File name cannot be empty. Please enter a valid file name.")
        } else {
            break
        }
    }

    // Prompt the user for the specified value to search for
    var search_value:Str
    while True {
        println("Enter the value to search for:")
        search_value = Console.readLine().trim()

        if len(search_value) == 0 {
            println("Error: Search value cannot be empty. Please enter a valid search value.")
        } else {
            break
        }
    }

    // Prompt the user for the columns to search the value for
    var search_columns:[Str]
    while True {
        println("Enter the name or names of the columns to search for (comma-separated):")
        search_columns_str:Str = Console.readLine().trim()

        if len(search_columns_str) == 0 {
            println("Error: Column name(s) cannot be empty. Please enter a valid column name or names.")
            continue
        }

        search_columns:[Str] <- search_columns_str.split(",")
        invalid_columns:[Str] <- []
        for column in search_columns {
            if column not in csv_file.headers {
                invalid_columns << column
            }
        }

        if len(invalid_columns) > 0 {
            println("Error: Invalid column name(s): " + invalid_columns)
            continue
        } else {
            break
        }
    }

    // Initialize the row count
    row_count:Int <- 0

    // Try to open the CSV file
    try {
        // Specify the delimiter as a comma (",")
        delimiter:Str <- ","
        file:IO.FD <- open(file_name, IO.r)
        csv_file:CSV.Data <- CSV.read(file, delimiter)
        close(file)

        // Check if the CSV file is empty
        if len(csv_file) == 0 {
            println("The CSV file is empty.")
            return 0
        }

        // Loop through the rows of the CSV file and count the number of rows that contain the specified value
        for row in csv_file {
            for column in search_columns {
                if search_value in row[column] {
                    row_count <- row_count + 1
                    break
                }
            }
        }

        // Handle the case where the specified value is not found in any row of the file
        if row_count == 0 {
            println("The value \"" + search_value + "\" was not found in the specified column(s) of the CSV file.")
            return 0
        }

        // Display the result to the user
        println("The CSV file contains " + row_count + " rows that contain \"" + search_value + "\" in the specified column(s) \"" + search_columns_str + "\".")

    }
    // Catch errors and handle them
    catch e:Exception {
        println("Error: " + e.message)
        return 0
    }

    // Return 1 to indicate successful execution
